<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
final class ProcessingOverlayMarkupTest extends TestCase
{
    public function testTargetFormsUseSharedMarkersAndMessages():void{$root=dirname(__DIR__,2);$employee=(string)file_get_contents($root.'/resources/views/human-resources/employees/_form.php');$compose=(string)file_get_contents($root.'/resources/views/company-notices/create.php');$review=(string)file_get_contents($root.'/resources/views/company-notices/review.php');foreach([[$employee,'Creating employee and sending notifications…'],[$compose,'Preparing company notice preview…'],[$review,'Publishing company notice and sending emails…']] as [$view,$message]){self::assertStringContainsString('data-processing-form',$view);self::assertStringContainsString($message,$view);self::assertStringNotContainsString('novalidate',$view);self::assertStringNotContainsString('<script',$view);self::assertStringNotContainsString('style=',$view);}self::assertSame(1,substr_count((string)file_get_contents($root.'/resources/views/layouts/app.php'),'processing-overlay.php'));self::assertStringContainsString('<a class="btn btn-secondary" href="/company-notices/create">Back to Edit</a>',$review);self::assertStringNotContainsString('name="review_token" value=',substr($review,0,strpos($review,'data-processing-form')));}
    public function testSharedOverlayHasInactiveAndAccessibleSemantics():void{$view=(string)file_get_contents(dirname(__DIR__,2).'/resources/views/components/processing-overlay.php');foreach(['data-processing-overlay','hidden','aria-hidden="true"','role="status"','aria-live="polite"','aria-busy="true"'] as $value)self::assertStringContainsString($value,$view);self::assertStringNotContainsString('<script',$view);self::assertStringNotContainsString('style=',$view);}
}
